-- Generated source references; not native quest records.
local addon = WordHunterWoW_Addon
local compat = addon and addon.Compat
local flavor = compat and compat.GameFlavor and compat.GameFlavor()
if not (flavor == "retail") then return end
local pack = WordHunterWoW_QuestSources and WordHunterWoW_QuestSources["multilanguage-retail"]
if not pack then return end
pack.loaded = true
local quests = pack.locales.enUS

quests[25718] = { id = 25718, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "How Best to Proceed", description = "Your demon-slaying down there bought our scouts enough time to get a good look at that druid.  My intelligence tells me that his name is Marl Wormthorn... a rogue Gilnean druid of substantial power.  He resides in Maldraz, the large, twisted tree at the center of the forest, and is protected from harm by some strange force.  Whether that force is of demonic or natural sources, we have yet to determine.\n\nSpeak with Elijah.  He may have some more information for you.", completion = "Rohan's sending YOU to slay his druid?  Very well.\n\nYou should know: Marl Wormthorn is as much demon as he is druid.  Even a druid of his power doesn't have a chance against the demonic energies that run so deeply through this land.  That does not, however, make him any less of an obstacle.", objectives = "Report to Elijah Dawnflight at the Sunveil Excursion in the Blasted Lands.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25719] = { id = 25719, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Demoniac Vessel", description = "We need a way to get Wormthorn's attention.  Something to break him out of his trance.  Something that's guaranteed to work.\n\nThe few types of wildlife that managed to make a foothold in the Tainted Forest are, without a doubt, affected by the land's latent energies.  Your task is to collect their body parts and find a way to combine them into a vessel.  If Wormthorn's trance is druidic, or even if it is demonic, a large enough vessel of tainted animal flesh should be able to break it.", progress = "Dawnflight's plan is a good one.  Do you have the vessel, {name}?", completion = "Brilliantly done, {name}.  We have what we need to break the worgen's trance.", objectives = "Kill the Tainted Black Bears, Tainted Nightstalkers, and Tainted Screechers in the Tainted Forest, and try to assemble their parts into a Demoniac Vessel.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25720] = { id = 25720, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Downfall of Marl Wormthorn", description = "Wormthorn's unnatural forest threatens our excursion's progress.  His trees' roots break our picks, his moss grows over our excavation sites, and his animals attack my men.  When it comes to digging, I'll take a demon-infested wasteland over a forest any day.\n\nTake the demoniac vessel and use it on Marl Wormthorn to pull him from his trance.  Return to me when he is no more.", progress = "I haven't time for this, {name}.  You came here for a reason, and it wasn't to chat.  Get back to work.", completion = "Hopefully, with this druid out of the picture, we can get back to our digging.  The world is full of powerful artifacts, {name}.  You just need to be willing to do what it takes to get to them.\n\nFeel free to take one of these.  The Reliquary is always happy to share some of its trove with fellow members of the Horde.", objectives = "Kill Marl Wormthorn at Maldraz in the Blasted Lands. You can use the Demoniac Vessel to pull him out of his trance.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25721] = { id = 25721, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fight the Flood", description = "I'm here because Muradin himself knew that this survey needed someone to keep these buffoons on their toes. They're all too scared of the wildlife to do a thing! If I'm to get them off their duffs, I'm going to need some cleanup done.\n\nWe've got an elemental problem, first off. The flood did such a number here that the water itself's gone hysterical.\n\nI bet you've never slapped the sense into an entire lake before, but I'm askin' it of you now. Whallop those elementals but good for me.", completion = "Well I'll be. There's someone around here that isn't a disgrace to Magni, bless his poor gravelly heart.\n\nJust for that, you get first crack at the ale, lad. But don't let it get to your bloody head! We've got more gorram work to do, and I won't tolerate you lettin' up early!", objectives = "Kill 10 Flood Elementals.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25722] = { id = 25722, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sedimentary, My Dear", description = "The destruction of the Stonewrought Dam was no small thing, <lad/lass>. We're here to find out just how bad the damage is. A mighty load of water's rampaged through here, and if it's disturbed the earth too far, we could be in for worse later on.\n\nWe can tell a lot from studying the sediment of the flooded area. I need as many soil samples as I can get, so if you could head out there and collect some more, I'd much appreciate it.", progress = "Let's see the sediment, then.", completion = "Ah, well. The good news is, these will do perfectly. The bad news is I can tell they're the wrong color for topsoil here, even drunk as I am.\n\nThat means things aren't looking good for the area, {name}. But we've got more tests to run before we hang up the towel.", objectives = "Collect 8 Flood Sediment Samples.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25723] = { id = 25723, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Thresh Out of Luck", description = "The local wildlife's all messed up from the flood, it seems. This fen used to be full of crocolisks, but I haven't spotted a single one.\n\nWhat I have spotted are threshadons. Never used to be any here, so the flood must've swept them all right out of Loch Modan.\n\nLucky for us, because they're tastier than crocolisks, and I'm running low on provisions. Bring me back some threshadon meat for the camp, and I'll gladly pay you for it.", progress = "Are they meaty ones? Let's have a look.", completion = "Lovely. These'll fry up nice, and the camp'll be spared a week of mushroom biscuits.", objectives = "Collect 8 Threshadon Chunks from Displaced Threshadons.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25724] = { id = 25724, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Frostmane Aggression", description = "The cataclysm has thrown the balance of power in Dun Morogh into question, {name}. Without warning, a wave of troggs emerged from the caves near Gnomeregan and overran the Frostmane trolls. The trolls have been migrating east ever since.\n\nThere has always been a Frostmane presence up on Shimmer Ridge, to the northwest, but with the migration, the trolls now surround us. We can't allow the trolls to use this position to their advantage. While my men hold the line in the east, strike against Shimmer Ridge.", completion = "We should be able to focus our efforts on the rest of the trolls to the east, but there's still the matter of the wendigos in the Grizzled Den.", objectives = "Kill 5 Frostmane Seers and 7 Frostmane Snowstriders on Shimmer Ridge.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25725] = { id = 25725, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fenbush Berries", description = "We're good on provisions, but we're in need of some medicine. Half the camp's fiercely hung over, and a remedy's in order.\n\nLuckily, I know a good folk remedy taught to me by my dear old mum. We just need some local ingredients.\n\nGather me some fenbush berries, if you would. They keep to where there's water and shade, so look along the shore and near other plants.", progress = "How much've you got?", completion = "These'll do nicely. I'll have the lads back on their feet as soon as I make these somewhat edible.", objectives = "Collect 15 Handfuls of Fenberries.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25726] = { id = 25726, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Dumpy Job", description = "Alright, I need you to help me find my dumpy level.\n\nWhat's that look for? That's right! I said my dumpy level! It's a piece of significant surveying equipment!\n\nI didn't name the bloody thing, alright? Go look it up! All I did was leave it on a rock long enough for one of those horrible oozes to swallow it up. The place is crawling with 'em, but one of them should still have it inside.", progress = "Did you find the dumpy?", completion = "Oh good, it's undamaged! Thanks a lot.\n\nYou ah, you might want to wipe yourself off a bit there.", objectives = "Obtain a Dumpy Level from a Silty Ooze.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25727] = { id = 25727, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Drungeld Glowerglare", description = "The Dark Iron clan is up to no good out here. And if that surprises you, you're thicker than the addled blotters over in that tent. Muradin may pay lip service to those sooty cretins back in Ironforge, but out here all bets are off.\n\nWe had a raid against the camp last night, and one raid is too many. Their leader's a stout fellow by the name of Glowerglare, and he's hiding in the cave on the south bank of the river.\n\nBring me Glowerglare's beard as proof he's no longer a threat to us and Ironforge.", progress = "Let's see it, then.", completion = "Good riddance to bad rubbish! I'll burn the foul thing later so it doesn't stink up the camp.", objectives = "Kill Drungeld Glowerglare and take his beard.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25728] = { id = 25728, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mr. P's Wild Ride", description = "Now Mr. P just needs an angel to help him navigate. Will you be that angel, <mister/miss>? With you helping we can go out into the crag and kill bunches and bunches of Horde! Waddya say? Come on, <mister/miss>! PRETTY PLEASE WITH SUGAR ON TOP?\n\nIf we kill enough Horde, Mr. Fallowmere will buy us all ice cream!", completion = "<Lord Fallowmere coughs.>\n\nThis is awkward...\n\nGood job out there with the robot. You caught me a little off guard. I didn't realize the little girl was so...\n\n<Lord Fallowmere points to his temple and twirls his finger around.>\n\nSpecial...\n\nWell, whatever gets the job done, right? Am I right?\n\nProbably.\n\nHave some ice cream.", objectives = "Kill 20 Goblin Technicians and 5 Goblin Harvesters.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25729] = { id = 25729, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gerenzo the Traitor", description = "<The Gnomecorder comes to life with a loud buzz.>\n\nCome in, {name}! Are you zhere? I have noted on ze map that you are near ze Cragpool Lake vater vheel, is that correct?\n\nIt vould appear that ze Venture Co. has holed up at ze vheel. Have a look around vhile you are up zhere. If you happen to zee a traitorous gnome by ze name of Gerenzo Wrenchwhistle, put your boot firmly up his keester for me and for Gnomeregan! I vill pay handsomely!", completion = "<The Gnomecorder buzzes loudly.>\n\nVonderful! That's von more name I can scratch off of my list!\n\nI vill be in touch.\n\nXakxak, out!", objectives = "Kill Gerenzo Wrenchwhistle.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25730] = { id = 25730, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "BEWARE OF CRAGJAW!", description = "By order of people not wanting to get themselves devoured whole by a really huge fish, Cragpool Lake is OFF-LIMITS! Someone decided to up and put a huge, dwarf-eating fish in the lake.\n\nIt is strongly recommended that you stay out, however, if you are the heroic type and have a few friends around, do us all a favor and kill the damned thing! Maybe I can get some fishing done then, eh?\n\nIf you manage to actually do it, meet me back at Windshear Hold for a reward.\n\n-Ol' Irongoat", progress = "You kill the beast?", completion = "Well I'll be a monkey's uncle. You actually got the beast, eh? Well, a deal's a deal! Here's your reward!", objectives = "Kill Cragjaw and take Cragjaw's Huge Tooth.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25731] = { id = 25731, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Bird in Hand", description = "It's time to get to the bottom of this. We need to interrogate the matron of these beasts, Marion Wormwing. We'll capture her alive. Here's the plan:\n\nThe harpies communicate across the ridge using a series of signal fires. If we extinguish one, Marion is sure to come investigate.\n\nYou fight her as a distraction while I sneak up behind and grab her. I'll leave the questioning to you. Let's get her, {name}!", progress = "Marion used to visit the shrine here. Skylord Omnuron tried to give the harpies the benefit of the doubt, but I never trusted her.", completion = "So the Harpies are tools of some sort of dragon - \"Sethria.\"\n\nBut what are the dragons doing to those eggs? And what's this 'special' egg that Sethria wanted so badly?\n\nThis is beyond me, {name}. I've given a report to Skylord Omnuron - he'll know what to do next.", objectives = "Extinguish a Harpy Signal Fire to get the attention of Marion Wormwing. Fight her until Thisalee subdues her, then question the harpy matron.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25732] = { id = 25732, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Bone to Pick", description = "We did it!\n\nGnaws is down, and I have our shiney!\n\nThat's good news.\n\nDarn shiney is cursed treasure - makes everyone who touches it a skeleton.\n\nThat's bad news.\n\nThese cursed pirates say the Gilblin King has the secret to remove the hex.\n\nThat's good news.\n\nI can't step foot outside the reef or I'll be cursed forever.\n\nThat's bad news.", progress = "So, {race}...\n\nYou gunna remove this curse, or what?", completion = "This is it?\n\nHow is this gunna remove - wait a minute...", objectives = "Budd wants you to collect the Pewter Pounder from King Gurboggle at Gurboggle's Ledge.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25733] = { id = 25733, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Get Out Of Here, Stalkers", description = "Thelgen Rock's an important site here. We need to use it to study the bedrock formations an' such.\n\nOf course, it can't be that easy, so Thelgen Rock's also full of giant cave stalkers. Big as a dwarf and twice as hungry. Like I said, these fancy-lads are researchers, not warriors, so if I want them to get anything done you're gonna have to help me clear the filthy bugs out.\n\nKill as many of the blighters as you can and I'll make it worth your while, {name}.", completion = "Good job. I wouldn't be surprised if the horrid things had eggs in there somewhere, but it'll do for now.", objectives = "Kill 7 Cave Stalkers and 7 Leech Stalkers.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25734] = { id = 25734, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Down In Thelgen Rock", description = "I'm feeling slightly less wobbly now, so I'm going to start setting up the level for my final measurements here. There's one last thing I need from you.\n\nThere's a seismograph set up deep within Thelgen Rock to record any movements in the earth. If things have been continuing to shift since the cataclysm, this'll tell us.\n\nThe seismograph's at the very bottom of the cave; find it and bring the record it's created back to me.", progress = "Let's see what we've got, aye?", completion = "Wonderful, lad. This should be all we need. Let's have a look.", objectives = "Retrieve the Thelgen Seismic Record from Thelgen Rock.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25735] = { id = 25735, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Incendicite Ore", description = "Thelgen Rock over yonder is something of a natural wonder. It's the only known source of incendicite in the world!\n\nThe stuff's rare, highly sought, and ridiculously explosive. Hit it with a steel mining pick and you'll set off a fireworks show that'll put a room full of goblins to shame.\n\nLuckily, I've developed a spark-proof pick for such tasks. I'll loan it to you if you bring me back some incendicite ore, and I'll split you in on the profits, of course.", progress = "Well, you look like you're in one piece.", completion = "Glorious! Beautiful stuff, this ore.\n\nGood on you for not droppin' your pick. Last person I sent out let the butt end hit the floor, and that part's not sparkproof.", objectives = "Collect 8 pieces of Incendicite Ore.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25736] = { id = 25736, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Floodsurge Core", description = "This is all that's left of the huge elemental that attacked you: a frothing orb of water that continues to fight your grip.\n\nForba might appreciate seeing proof that you helped stop another threat to the camp.", progress = "Eh? What's that you've got there?", completion = "The thing's still got some fight in it! Amazing!\n\nYou're a tough one, {name}. It's much appreciated. I'd say a reward is in order before you head out.\n\nKeep doin' your best for Ironforge, you hear? And if you ever see my sister, say hello for me.", objectives = "Deliver the Floodsurge Core to Forba Slabchisel.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25737] = { id = 25737, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tenuous Negotiations", description = "From what I've learned about these water-goblins, this should work.\n\nI've crafted a shark-tooth necklace from the items you scrounged up. Not only is it a shiny trinket, but it's a memento of Gnaws' death. There's no telling how many gilblins were eaten alive by that monster.\n\nOffer the necklace to the gilblin leader. In exchange, I need an artifact called The Pewter Pounder.\n\nAnd be quick about it, kid. I'm already beginning to miss my flesh...", objectives = "Speak to King Gurboggle.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25738] = { id = 25738, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Shallow End of the Gene Pool", description = "<Gurboggle inspects the Gnaws Tooth Necklace for a moment.>\n\nNot bad, {race}, assuming it's the real thing. I'll hafta send one of my boys out to make sure your story checks out.\n\nIn the meantime, you're gunna do a little somethin' for me, see, 'cause this little trinket ain't worth givin' up The Pewter Pounder - not by a longshot!\n\nMy cousin, Gilblingle, has had his eye on my throne for years. Dumb as a bag of coral, that one - but still dangerous.\n\nYou take him out, and then we'll talk.", objectives = "King Gurboggle wants you to kill Gilblingle in Gurboggle's Ledge.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25739] = { id = 25739, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "If the Horde Don't Get You...", description = "<Captain Kosak coughs weakly.>\n\nWas traveling up Webwinder Path, coming from Northwatch Expedition Base Camp in the south. Ambushed. Not by Horde. Spiders. Big, ugly, hairy, nasty spiders.\n\nFought off dozens, maybe hundreds. Lost count. Overtaken by their queen. She took a chunk right out of me. Barely made it out alive. Might be dying.\n\nMore of my men coming. Must provide safe passage. Kill spider queen.\n\n<Captain Kosak passes out.>", completion = "<Captain Kosak forces a smile at you.>\n\nDon't worry about me. Should be ok now that big hero killed the spider queen.\n\nCan get reinforcements through safely now.", objectives = "Kill Queen Silith.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25740] = { id = 25740, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fact-Finding Mission", description = "The dragon Sethria must be stopped. We know that her roost is south of here, along the southern cliffs of Hyjal, but beyond that we know little else.\n\nI have sent Thisalee on a fact-finding mission to Sethria's Roost. She specifically requested your help - evidently you made quite an impression with the young druid.\n\nMeet Thisalee just beyond the tunnel leading to Sethria's Roost. And remember, this is a fact-finding mission - don't do anything crazy!", completion = "Ah, {name}! I was hoping to see you out here.\n\nWhat, Omnuron calls this a 'fact-finding mission?' Bah! Facts are best found on corpses.\n\nLet's do some damage.", objectives = "Report to Thisalee at the entrance to Sethria's Roost in Mount Hyjal.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25741] = { id = 25741, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Preparations for the Future", description = "Poisoned travelers are becoming a common occurrence around Windshear Hold. Why just the other day a Northwatch Captain fell prey to the spiders of the Webwinder Hollow. He would have died to the poison had it not been for my anti-venom. Sadly my stock of anti-venom is almost completely depleted.\n\nIf you're heading south towards Webwinder Hollow, would you kindly recover Deepmoss venom sacs for me? You should be able to acquire them from Deepmoss spiders.", progress = "Have you recovered the venom sacs I requested?", completion = "This will keep us stocked on anti-venom for the foreseeable future. Thank you, {name}!", objectives = "Collect 10 Deepmoss Venom Sacs.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25742] = { id = 25742, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "What? This Old Thing?", description = "A deal's a deal.\n\nI present you - mysterious {race} stranger - with the one and only Pewter Pounder.\n\nYou may approach and receive this illustrious gift.\n\nThere, now, while it may look to be a simple hammer to the untrained eye, there are surely many hidden properties that will only manifest themselves when the appropriate situation arises.\n\nTake good care of this treasure, stranger. It has been in my royal possession for... well... days, now!", objectives = "Bring The Pewter Pounder to Harrison at The Accursed Reef.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25743] = { id = 25743, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Decisions, Decisions", description = "This is no magic solution to my curse! It's just a hammer!\n\nI may be crazy, but I'm not stupid.\n\nThere's NO WAY I'm gunna use this to break my shiney - not after all I've gone through to get it.\n\n<Budd pauses in thought for a moment.>\n\nBut that means I'm stuck down here for eternity...\n\nI had just learned to sail, you know.\n\nOhhh... I can't decide.\n\nHere, you take the hammer and I'll just set the shiney down and look the other way.", completion = "Oh, what might have been...", objectives = "You must use The Pewter Pounder to destroy The Pewter Prophet.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25744] = { id = 25744, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Negotiations", description = "{name}, great job defending the Speedbarge! I've got something else that I need you to help out with.\n\nI've sent Crazzle Sprysprocket and Kravel Koalbeard northeast to negotiate with the centaur survivors. Their Splithoof Heights is dripping with oil!\n\nI figure those smelly half horses won't know what they've got and we'll get the rights to pump up that black gold for a song, but I'd feel better if you took charge of the talks.\n\nWhat do you say?", completion = "<Crazzle gets a gleam in his eye.>\n\nI've got Kravel Koalbeard up there talking to one of their chiefs, but now that you're here, we'll have the rights to pump up their oil in no time!", objectives = "Speak with Crazzle Sprysprocket at the Splithoof Heights in Thousand Needles.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25745] = { id = 25745, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Negotiations", description = "{name}, great job defending the Speedbarge! I've got something else that I need you to help out with.\n\nI've sent Riznek and Trackmaster Zherin northeast to negotiate with the centaur survivors. Their Splithoof Heights is dripping with oil!\n\nI figure those smelly half horses won't know what they've got and we'll get the rights to pump up that black gold for a song, but I'd feel better if you took charge of the talks.\n\nWhat do you say?", completion = "<Riznek gets a gleam in his eye.>\n\nI've got Trackmaster Zherin up there talking to one of their chiefs, but now that you're here, we'll have the rights to pump up their oil in no time!", objectives = "Speak with Riznek at the Splithoof Heights in Thousand Needles.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25746] = { id = 25746, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sethria's Brood", description = "First order of business is to thin the herd here. This place crawls.\n\nLet's start slaughtering these dragonkin and worry about why they're here later.", completion = "You're good at this.\n\nI like you.", objectives = "Slay 12 of Sethria's Minions: Any combination of Twilight Dragonkin or Twilight Dragonkin Armorers.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25747] = { id = 25747, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Looking Forward", description = "The Admiral used the information you gathered for him to make a forward post under the terrace to our west. He's been preparing there for some kind of attack against the naga.\n\nYou should go to him immediately and inform him of the scope of what you've witnessed. Our force is small, and I fear for our soldiers if we charge in too recklessly.\n\nTake my sea horse. It knows the way.", completion = "Good to see you again, {class}. I almost thought we'd lost you to the Wavespeaker's fool errand.\n\nDid anything come of it?", objectives = "Find and speak to Admiral Dvorek under the southern terrace in the Ruins of Vashj'ir.\n\nUse Wavespeaker Valoren's sea horse to reach the forward post quickly.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25748] = { id = 25748, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Clear Goals", description = "I see. The news you bring is grim, but I was not entirely unprepared for such possibilities. Without any effective scouting of naga numbers, I knew our plan was risky, but that's why we established this forward post.\n\nLet me put it to you plainly, {class}. If we do not keep the naga off-balance, they will bring the fight to us. We do not have the structures or the men to mount a defense, so that is not an option.\n\nWe need more time. Can you thin their numbers to the south?", completion = "More naga are amassing to the south than reported too it seems. We shall have to move quickly then.", objectives = "Kill 10 of the naga forces building up on the ground level, under the southwestern terrace.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25749] = { id = 25749, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Not Entirely Unprepared", description = "I overheard your conversation with the Admiral. I know what we're doing sounds insane, but we really don't have much choice. There are people back at that cave that are depending on us.\n\nI've stationed lookouts on various ledges in the immediate area. They're burning ammo fast on the scattered naga scouts. Can you bring them more crossbow bolts to buy us some extra time?", completion = "You are perhaps the most dependable person I've ever met. I wish I could have more men half as thorough as you.", objectives = "Deliver 8 Bundles of Crossbow Bolts to Alliance Lookouts positioned on ledges under the southern terrace.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25750] = { id = 25750, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Curious Distraction", description = "Hah! Did you see the Admiral giving me dirty looks and decide to throw some sympathy my way? I've pretty much lost hope of making him understand that these ruins offers us some opportunity to salvage some usefulness out of this whole  mess.\n\nI'd actually hoped that you might turn up again - you seem like the only one I can rely on. I've seen a few tablets like this one spread about the nearby ruins and I put together a rubbing kit for transcribing them. Up to the task?", objectives = "Transcribe the 4 Highborne Tablets.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25751] = { id = 25751, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Properly Inspired", description = "Hello! I've been scrambling, scrambling to prepare for the Admiral's assault. He's got high hopes and high plans to blow all kinds of things sky high! ...or water high? That would do.\n\nBlowing things high takes EXPLOSIVES! I don't have explosives. It's saddening. Very saddening.\n\nI've been properly inspired to improvise though, and the solution has become apparent. The bulbs on the seaweed hanging from the ruins contain a surprisingly volatile gas. Maybe you might gather some for me? Pretty Please?", progress = "Tick, tock, tick, tock. Always in such a hurry. No time for innovation. What I wouldn't give for a lab again!", completion = "You are brave indeed! I've seen you battling all manner of murloc, naga, and pointy-toothed fish, but that was nothing! The way you just sling those kelp bulbs under your arm like that is a whole new kind of fearless. BOOM! You could blow up at any second.\n\nYou're my kind of {race}.", objectives = "Gather 8 Bloated Kelp Bulbs hanging under the southwestern terrace.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25752] = { id = 25752, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Swift Action", description = "We have everything we need to begin the attack.\n\nIf your claims were correct, you would do well to make sure you cling tight to your mount as we make the attack. Anyone who gets caught in the open water isn't likely to out-swim a naga.\n\nKill as many as you can as we make the attack run and we'll rendezvous on the broken ledge of the terrace above once we've expended our explosives. Hopefully by that point there will be few enough that we can finish them off the old-fashioned way.", completion = "You did great up there! You devastated their ranks, but there were far more than we accounted for, and most of our men went down out there in the masses of naga.\n\nWe'll need to hold this position as long as possible to buy them time. Hopefully some of them will still make it to the rendezvous.", objectives = "Speak to Engineer Hexascrub just outside of the building to join the assault, then use your improvised explosives to kill 100 Azsh'ir Soldiers, 20 Azsh'ir Wave Screamers, and 12 Azsh'ir Archaens.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25753] = { id = 25753, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fallen But Not Forgotten", description = "That was a disaster! Most of our men went down to spears before making it anywhere near the rendezvous.\n\nWe're only going to be able to hold this position for so long before the naga overrun us. We need to get out there to the southwest and save as many of the men as we can find - do anything you can.\n\nThey won't last long. Please hurry!", completion = "Thank you. Truly.\n\nWe need to get these men moving as soon as possible. I'll meet you back at the forward post soon, I'm sure.", objectives = "Rescue 6 Injured Assault Volunteers.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25754] = { id = 25754, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gauging Success", description = "Vicious louts... they did a lot of damage with those spears.\n\n<The admiral winces slightly as he clutches a wound on his side.>\n\nWe'll hold here as long as we can for all the men to make it. I need someone to scout their numbers to see how much damage we did.\n\nOne of the biggest groups of them was around the corner on the northwest portion of this round terrace, and the other was a bit farther to the north in the small tunnel, also on this middle level of the ruins.\n\nUp for some scouting?", completion = "Still so many? They must want something very important here to come in such numbers.\n\nI will be honest with you, {name}, because you deserve at least that: I don't know how much hope there is. We will retreat shortly, but we won't be able to defend ourselves when they strike back. We don't have anywhere to run... we're running out of options.\n\nI'm sorry, I should keep such thoughts to myself. Do me a favor and don't mention any of that to the men. I'll figure something out.", objectives = "Scout the northwestern portion of the circular terrace and the tunnel under the main stairs to the north. Both locations are on Nar'shola Terrace, the middle level of the ruins.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25755] = { id = 25755, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Visions of the Past: The Slaughter of Biel'aran Ridge", description = "Look, I know this is asking a lot during a time like this, but I need you to tear yourself away from this defeat for a moment.\n\nI will tend to these soldiers - you need to find the location of that battle with the Kvaldir General to the west that you told me about. You should be able to glimpse more of the Battlemaiden's experiences from there. I have a strong feeling that the key to defeating these naga will lie with that Battlemaiden.\n\nPlease hurry - I will do everything I can to buy you time.", completion = "You're finished! Just in time. I don't think we could have held them much longer.\n\nAn artifact? Could this be something we can use against the naga? I suppose that would require finding it.\n\nWe may have to attend to more pressing matters first, until an opportunity to pursue this further presents itself.", objectives = "Witness the continuing story of the Battlemaiden by using her broken blade at the site of the Kvaldir General's death.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25756] = { id = 25756, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Get Zherin!", description = "If we're going to get those oil drilling rights, we need to know what the Horde is offering. How can we win if we can't do them one better?!\n\nTheir negotiator, Trackmaster Zherin, is up there talking with one of their khans right now. Why don't you head up and persuade him to hand over the Horde's proposal?\n\nYou don't have to kill him... we're not savages! Just rough him up a bit.", progress = "Do you have the Horde's proposal? What are they offering for the drilling rights?", completion = "What?! How'd they get that much gold to offer?\n\nWe don't have that kind of money!", objectives = "Obtain the Horde's Proposal.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25757] = { id = 25757, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Get Koalbeard!", description = "If we're going to get those oil drilling rights, we need to know what the Alliance is offering. How can we win if we can't do them one better?!\n\nTheir negotiator, Kravel Koalbeard, is up there talking with one of their khans right now. Why don't you head up and persuade him to hand over the Alliance's proposal?\n\nYou don't have to kill him... we're not savages! Just rough him up a bit.", progress = "Do you have the Alliance's proposal? What are they offering for the drilling rights?", completion = "What?! How'd they get that much gold to offer?\n\nWe don't have that kind of money!", objectives = "Obtain the Alliance's Proposal.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25758] = { id = 25758, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Gap in Their Armor", description = "Do you see what they're doing here? They're affixing armored plates onto the Dragonkin. A page out of Deathwing's book, I suppose.\n\nThose Twilight Juggernauts look like they'll be invincible once they're complete. There's got to be a way around that armor plating!\n\nRun out there and fetch some of the Twilight armor plates that are waiting to be installed. We'll figure out how to beat this.", progress = "Did you get a hold of some plates? Did you have to kill anyone to get them?\n\nI hope so.", completion = "Look at these things. Ugh, the runes make my eyes hurt. This one here is meant to sear flesh? Seriously? Ouch! Wait a minute...\n\nThese plates are designed to be riveted directly into flesh. The pain must be unbearable!", objectives = "Gather 8 Twilight Armor Plates.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25759] = { id = 25759, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hammering It Out", description = "The rift that was here left behind this strange device, but why?\n\nSomeone in a capital city may have more information.", progress = "What's this then?  Another device?", completion = "Not another one! {name}, these devices have been springing up all around Azeroth. We know that they can instigate elemental disturbances in the area, including causing tears in the elemental planes.\n\nThe devices stink of Twilight's Hammer.  The engravings covering the surface and the captured elemental essence implicate Cho'gall and his minions are behind this.\n\nIf you find more of these, please bring them to me or one of my associates. We need to learn more about what's behind this attack.", objectives = "Take the Mysterious Device to Orgrimmar, Undercity, Silvermoon City or Thunder Bluff and show it to an Earthen Ring Representative.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25760] = { id = 25760, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Visions of the Past: The Invasion of Vashj'ir", description = "The shard you recovered looks to be of naga origin. I had hoped to find a strong focal object like this for a spell I've been working on that would allow us to glimpse into the recent past.\n\nI've enchanted the blade, but you'll have to take it to a place where we know its owner was. I want you to travel back to the site where you found it and use the blade.\n\nPerhaps we can uncover more behind what the naga are doing here. Or even better, maybe we'll uncover a weakness that will give us a better chance.", completion = "A Battlemaiden? I never heard of such a thing.\n\nThe way you explain it, it sounds like the naga forces are far greater in scope than the Admiral could possibly have realized. We might be able to learn more through the blade if we can find other locations where this Battlemaiden was present, but the information you gave me makes me fear for the admiral and his soldiers. We must warn them.", objectives = "Use the Blade of the Naz'jar Battlemaiden at the battle site at the southeast end of the ruins.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25761] = { id = 25761, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Disassembly", description = "We have to stop these juggernauts before they're completely encased in armor. Right now they're vulnerable, but only if we pry aside the plates and hack at the marred flesh beneath.\n\nTake my shiv, and jam it between the plates of armored juggernauts to deprive them of their armor.\n\nOnce they break from their trance, you're in for a tough fight - keep prying loose that armor and stop those juggernauts!", progress = "Oh good.\n\nYou're still alive.", completion = "That was some fancy bladework, {name}!\n\nThere's one less threat for us to worry about in Hyjal.", objectives = "Use Thisalee's Shiv to awaken and kill 3 Twilight Juggernauts. The shiv can be used multiple times to tear down a Juggernaut's armor.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25762] = { id = 25762, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Ancient Brazier", description = "What do we have here? A {race}? Come to steal our land with your honeyed tongue and promises?\n\nYou do not fool me. I have lived a long time, and I know what dealing with your kind means. But the khans do not listen to their elders like they used to.\n\nSince you are here, I will put you to use. When the waters rushed in, the great water spirit, Aquarian, doused the Ancient Brazier deep inside of Splithoof Hold.\n\nUse this brand to reignite the brazier. Aquarian is sure to come. Bring me the Sacred Flame.", progress = "You have the Sacred Flame? Do not speak to me unless you do, {race}!", completion = "You did this favor to ingratiate yourself with me, but I will not sing your praises.\n\nI know what is to come. Where the sea failed, the great air spirit will strike you and your people down for your many transgressions against the elements.\n\nBegone from my sight!", objectives = "Reignite the Ancient Brazier and obtain the Sacred Flame.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25763] = { id = 25763, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Codex of Shadows", description = "<This elaborate book contains hundreds of vellum pages bound within a slate cover. It's written in many languages, most unfamiliar. Carefully inked illustrations depict sorcerers or even entire buildings vanishing into curtains of shadow.>\n\n<Many illustrations depict magical artifices like those you see around camp. You suspect the dragon Sethria is trying to keep something hidden. Thisalee will want to hear about this!>", completion = "They're doing what?\n\nThey're cloaking something? Of course - so our aerial scouts can't see anything with our eagle-eyes!", objectives = "Report what you've discovered to Thisalee Crow at Sethria's Roost in Mount Hyjal.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25764] = { id = 25764, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Egg Hunt", description = "Skylord Omnuron wants us to find Aviana's Egg, and I can almost guarantee you it's cloaked by one of Sethria's shadow devices.\n\nSearch around the camp for shadow cloak generators and shut those things down until you find the egg.\n\nOnce you've unveiled it, I'll call out to the other druids. Defend that egg until we can carry it off to safety.\n\nGo get that egg, {name}!", completion = "We did it, {name}! Aviana's Egg should soon be tucked safely in the boughs of her shrine.\n\nDo you think this means she'll really return to us?", objectives = "Disable the Shadow Cloak Generators until you unveil Aviana's Egg. Once the egg is unveiled, defend it until the Druids of the Talon can carry it to safety.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25765] = { id = 25765, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tell 'Em Koko Sent You", description = "Northwatch could really use a powerful {race} like you. We're taking a beating in the Southern Barrens and need your help! Are you interested in lending the Alliance a hand?\n\nThe bomb? Yea, it's a problem, but Stonetalon isn't exactly prime real estate. This place was a dump before the Horde sunk their claws into it!\n\nI'll leave the choice in your hands. If you want to help us out in the Barrens, take my horse, Blue Steel. He's grazing at the crossroads south of here. He'll get you past the orc blockade.", completion = "Kosak sent you, eh? Surprising. I thought for sure that he'd be dead by now.\n\nWell if you made it past the blockade then you definitely have something that we can use.\n\nNow, do you have any news of the Horde? What are they doing? Where are they going? Tell me everything.", objectives = "Report to Force Commander Valen at the Northwatch Expedition Base Camp in Stonetalon Mountains.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25766] = { id = 25766, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Arcane Legacy", description = "The rage of the elements has unearthed a hidden Highborne city in the heart of Stonetalon Mountains.\n\nDirectly southwest of here, through Sishir Canyon, you will find the Ruins of Eldre'thar. Within the ruins lie treasures untouched by mortals for ten thousand years!\n\nTake this device and use it on the Highborne ghosts that inhabit the ruins. It will... put their souls to rest and also collect valuable data which I may peruse at a later date.", completion = "I assure you, simpleton, the spirits you captured are at rest. Do not let their protests move you.", objectives = "Use the Highborne Prison to bind 5 Highborne Spirits.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25767] = { id = 25767, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Capturing Memories", description = "The great cataclysm has unearthed a forgotten Highborne city within Stonetalon Mountains. You must venture southwest to the Ruins of Eldre'thar. Once you are there, search the area for ancient relics. Return the relics to me so that I may study them, {name}.\n\nGo! Lest we keep the arcanist waiting!", progress = "Have you recovered the ancient relics?", completion = "Wonderful! Arcanist Valdurian will be most pleased.", objectives = "Collect 8 Eldre'thar Relics.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25768] = { id = 25768, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bombs Away: Mirkfallon Post!", description = "Scout Commander Barus, stationed at Mirkfallon Post, to the northwest, has spotted the Horde bomb. The Krom'gar hot air balloon, with bomb attached, is currently at the new goblin fueling station at Mirkfallon Lake. This might be the opportunity we need to take that thing out once and for all.\n\nGather your things, {name}, and move out! Scout Commander Barus awaits your arrival at Mirkfallon Post.\n\nAnd {name}, your tenacity is a testament to the strength and fortitude of the Alliance!\n\nGlory be unto you!", completion = "I'm assuming you saw the Krom'gar hot air balloon on your way here. If not, get your eyes checked. It's hovering directly over the oil platform.", objectives = "Report to Scout Commander Barus at Mirkfallon Post in Stonetalon Mountains.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25769] = { id = 25769, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fallowmere Beckons", description = "You're still here? What are you waiting for, a personal engraved invitation? Lord Fallowmere beckons, fool! Go to him now!", completion = "Good to see you again, {name}. I have some news from Mirkfallon Lake.", objectives = "Speak to Lord Fallowmere at Windshear Hold in Stonetalon Mountains.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25770] = { id = 25770, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Keg Run", description = "Alright. We need to get this ale to where it's going right away!\n\nIronforge has sent out an expedition of surveyors to check the damage done to the wetlands when the dam burst. Forba Slabchisel's the one leading it...and believe me, you don't want to get on her bad side!\n\nShowing up with an armful of ale will help with that. Go and take this ahead to her, and she might even ask you to stick around for some work.", progress = "Aye? What've you got for me there?", completion = "Hah! Nice to see those addlebrained mountaineers knew to hand the ale off to a real man to get the job done.\n\nWelcome to my survey. If you're of the mind to help Ironforge by takin' over the intended jobs of some useless, lazy sods that call themselves dwarves, you're in the right place!", objectives = "Deliver the Mountaineer's Ale to Forba Slabchisel at Slabchisel's Survey.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25771] = { id = 25771, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "One Draenei's Junk...", description = "A shard of glimmering rock sits before you.  You sense that this item would be of value to someone within the Blasted Lands.", progress = "Well? Draenethyst?", completion = "Just a shard?  Pfuh!  This gets me nothing!  Take your reward and get out of my sight.\n\nSounds familiar?  It should, because I say it a thousand times per day.\n\nOh how I loathe this world.", objectives = "Return the Imperfect Draenethyst Fragment to Kum'isha the Collector in Blasted Lands.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25772] = { id = 25772, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kum'isha's Endeavors", description = "A glimmering sphere sits before you.  You sense that this item would be of great value to someone within the Blasted Lands.", progress = "Have you found a flawless draenethyst sphere?", completion = "Simply amazing.  I had doubted that anyone could find another sphere, yet here it is, pulsating in my hands.\n\nWell done, {name}!\n\nShould you find anymore--and I believe this to be an impossibility--return them to me and I shall reward you again.", objectives = "Bring the Flawless Draenethyst Sphere to Kum'isha the Collector in Blasted Lands.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25773] = { id = 25773, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Natural Occurrence", description = "This shard is all that is left from the rift that stood here before.  The connection between the shard and the rift is unknown, but perhaps someone more versed in the elements would know more.\n\nSeek out an Earthen Ring Emissary at any capital city.  This could be exactly what they are looking for.", progress = "You found this near an Elemental Rift?", completion = "Yes, {name}, this shard does explain the occurrence of the rift.  The elemental planes have been in chaos in Outland ever since Draenor was destroyed. These shards cause a weakness in the already damaged elemental planes and allow the elementals to cross into our world\n\nWe're still looking into how these rifts are appearing in Azeroth.  Keep bringing us the shards.  Every shard we get brings us closer to understanding how these rifts are appearing.", objectives = "Take the Elemental Shard to an Earthen Ring Emissary in Ironforge, Stormwind, Exodar or Darnassus.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25774] = { id = 25774, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fool's Gold", description = "We definitely DO NOT have the kind of gold that the Horde is offering. {name}, we have to do something or we're not going to be able to get those drilling rights!\n\nWait a minute! There was this report from an underwater survey that we did right after the Cataclysm struck. Something about some gold-looking ore that was pushed up from underground. That's it!\n\nHead west to the old stomping grounds of the centaur, Splithoof Crag and Splithoof Hold, and dig some up.", progress = "Once you return with enough of that pyrite, we'll give it a once over with a paint brush, pile it all up on a pallet, and send you back up with it to the chieftain.", completion = "Genius! Now, where's that gold paint? I know it's around here somewhere.", objectives = "Collect 8 Needles Pyrite Ore Chunks.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25775] = { id = 25775, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fool's Gold", description = "We definitely DO NOT have the kind of gold that the Alliance is offering. {name}, we have to do something or we're not going to be able to get those drilling rights!\n\nWait a minute! There was this report from an underwater survey that we did right after the Cataclysm struck. Something about some gold-looking ore that was pushed up from underground. That's it!\n\nHead west to the old stomping grounds of the centaur, Splithoof Crag and Splithoof Hold, and dig some up.", progress = "Once you return with enough of that pyrite, we'll give it a once over with a paint brush, pile it all up on a pallet, and send you back up with it to the chieftain.", completion = "Genius! Now, where's that gold paint? I know it's around here somewhere.", objectives = "Collect 8 Needles Pyrite Ore Chunks.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25776] = { id = 25776, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sethria's Demise", description = "While you've been raiding Sethria's nest, messages have been flying back and forth between here and the shrine. Skylord Omnuron was at first reluctant, but I've persuaded my fellow druids to risk a direct assault on Sethria herself.\n\nEveryone agreed to my plan... provided YOU spearhead the attack.\n\nTake this signal rocket and engage Sethria on the far ridge. When she reveals her true colors and shifts to her dragon form, fire the rocket and backup will arrive to help you!", progress = "If a minor dragon like Sethria can cause us so many problems, I hate to see what else Twilight's Hammer has in store...", completion = "Sethria is slain! I knew it was worth the risk.\n\nI'll stay here to look for survivors, but I imagine they'll want to see you back at the shrine.", objectives = "Slay the dragon Sethria. Once she reveals her true form, you will need to use the signal rocket to call in reinforcements!", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25777] = { id = 25777, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Onwards to Menethil", description = "This news needs to get to Menethil as soon as possible. I'll send you along on my fastest ram, {name}.\n\nHe knows the way, just make sure you're steady in the saddle and hold on tight.\n\nDon't dawdle around the camp. We've got to send word quickly!", progress = "Welcome to Menethil, stranger. I hope you've got good news or a stiff drink with you.", completion = "Let's take a look here.\n\nOh, this is just lovely. \"Significant geological instabilities\"? \"Threat of sudden, massive topological destabilization\"?\n\nNice to hear that somethin' bad might happen around here. I guess we'll just pick up our flooded town and fly it off somewhere safe!\n\nBah!", objectives = "Deliver the Slabchisel Report to Captain Stoutfist in Menethil Harbor.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25778] = { id = 25778, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fake Gold for Black Gold", description = "Now that the \"gold\" is ready, I want you to take it up to Khan Ablinh. He'll be so overwhelmed, I bet he'll offer to help us setup the drilling rigs. We could use the horsepower.\n\nHaha, get it? Horsepower?", progress = "What's this? That is a lot of gold you have there.", completion = "Just put it down on the ground, {race}.", objectives = "Deliver the Pallet of \"Gold\" to Khan Ablinh at the Splithoof Heights in Thousand Needles.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25779] = { id = 25779, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fake Gold for Black Gold", description = "Now that the \"gold\" is ready, I want you to take it up to Khan Blizh. He'll be so overwhelmed, I bet he'll offer to help us setup the drilling rigs. We could use the horsepower.\n\nHaha, get it? Horsepower?", progress = "What's this? That is a lot of gold you have there.", completion = "Just put it down on the ground, {race}.", objectives = "Deliver the Pallet of \"Gold\" to Khan Blizh at the Splithoof Heights in Thousand Needles.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25780] = { id = 25780, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Assault on Menethil Keep", description = "We'd barely pulled ourselves together after the flood when the Dark Iron hit the town. My men and I all rushed to defend the townsfolk, but the crazed fools retreated right into the keep itself.\n\nThey're holed up good, and we can't destroy the keep. Not with half the town in ruins already.\n\nTake my place, {name}. I'd take the leader on myself if he hadn't dealt me this blow. Enter the keep, slay Horghast, and bring this to an end!", progress = "Is he dead? Is Horghast dead?", completion = "He's dead! Thank the Makers...\n\nI don't like the looks of them, lad. The Dark Iron I've tussled with were never this crazy. Something's getting to these sods...", objectives = "Kill Horghast Flarecrazed.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[25781] = { id = 25781, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hammering It Out", progress = "What's this then?  Another device?\n\nProvided item:", completion = "Not another one! {name}, these devices have been springing up all around Azeroth. We know that they can instigate elemental disturbances in the area, including causing tears in the elemental planes.\n\nThe devices stink of Twilight's Hammer.  The engravings covering the surface and the captured elemental essence implicate Cho'gall and his minions are behind this.\n\nIf you find more of these, please bring them to me or one of my associates. We need to learn more about what's behind this attack." }
quests[25782] = { id = 25782, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hammering It Out", progress = "What's this then?  Another device?\n\nProvided item:", completion = "Not another one! {name}, these devices have been springing up all around Azeroth. We know that they can instigate elemental disturbances in the area, including causing tears in the elemental planes.\n\nThe devices stink of Twilight's Hammer.  The engravings covering the surface and the captured elemental essence implicate Cho'gall and his minions are behind this.\n\nIf you find more of these, please bring them to me or one of my associates. We need to learn more about what's behind this attack." }
